svg.script:
var startDate = new Date("2026-06-14T00:00:00+08:00");
var endDate = new Date("2036-06-14T00:00:00+08:00");
var CIRC = 2 * Math.PI * 56;

function pad(n) { return n < 10 ? "0" + n : "" + n; }

function update() {
  var now = new Date();
  var total = endDate.getTime() - startDate.getTime();
  var passedMs = Math.min(Math.max(now.getTime() - startDate.getTime(), 0), total);
  var ratio = total > 0 ? passedMs / total : 0;

  document.getElementById("ring").setAttribute("stroke-dasharray", CIRC.toFixed(2));
  document.getElementById("ring").setAttribute("stroke-dashoffset", (CIRC * (1 - ratio)).toFixed(2));
  document.getElementById("percent").textContent = (ratio * 100).toFixed(2) + "%";
  document.getElementById("passed").textContent = Math.floor(passedMs / 86400000);
  document.getElementById("remain").textContent = Math.ceil((total - passedMs) / 86400000);
  document.getElementById("stamp").textContent =
    now.getFullYear() + "-" + pad(now.getMonth() + 1) + "-" + pad(now.getDate()) + " " +
    pad(now.getHours()) + ":" + pad(now.getMinutes()) + ":" + pad(now.getSeconds());
}

update();
setInterval(update, 1000);
